create extension if not exists pgcrypto;
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,organization_id uuid references public.organizations(id) on delete set null,role text not null default 'owner',created_at timestamptz not null default now());
create table if not exists public.agents(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,name text not null,purpose text,status text not null default 'ready',created_at timestamptz not null default now());
create table if not exists public.workflows(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,name text not null,definition jsonb not null default '{}',status text not null default 'draft',created_at timestamptz not null default now());
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,company_name text not null,score integer,status text not null default 'new',metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.workflow_runs(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,workflow_id uuid references public.workflows(id) on delete set null,status text not null,started_at timestamptz not null default now(),finished_at timestamptz,duration_ms integer,result jsonb not null default '{}');
create table if not exists public.telemetry_events(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,run_id uuid references public.workflow_runs(id) on delete cascade,event_type text not null,agent_name text,latency_ms integer,status text,payload jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.billing_events(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,provider text not null,external_id text,event_type text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.organizations enable row level security;alter table public.profiles enable row level security;alter table public.agents enable row level security;alter table public.workflows enable row level security;alter table public.leads enable row level security;alter table public.workflow_runs enable row level security;alter table public.telemetry_events enable row level security;
create or replace function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and organization_id=org); $$;
create policy "org members agents" on public.agents for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy "org members workflows" on public.workflows for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy "org members leads" on public.leads for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy "org members runs" on public.workflow_runs for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy "org members telemetry" on public.telemetry_events for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
